export function swapMeal(plan,p,mealId,newRecipe){if(!allowedRecipes(p).some(r=>r.id===newRecipe))throw Error('This recipe does not match your food restrictions, kitchen, or preparation time.');const out=structuredClone(plan);const m=out.days.flatMap(d=>d.meals).find(x=>x.id===mealId);if(!m)throw Error('Meal not found.');m.recipe=newRecipe;return out;}
export function previousPerformance(history,exercise){return [...history].reverse().flatMap(w=>w.exercises||[]).find(e=>e.id===exercise);}
export function progression(history,exercise,p){const last=previousPerformance(history,exercise.id);if(!last?.sets?.length)return {weight:0,note:'Start light. Choose a weight that leaves 2–3 good reps in reserve.'};let load=Math.max(...last.sets.map(s=>s.weight));const expected=exercise.sets||last.plannedSets||routine(p).find(e=>e.id===exercise.id)?.sets||2;const top=last.formQuality==='controlled'&&last.sets.length>=expected&&last.sets.every(s=>s.reps>=exercise.reps[1]&&s.rpe<=8);const available=p.weights.split(',').map(Number).filter(n=>Number.isFinite(n)&&n>0).sort((a,b)=>a-b);const next=available.find(n=>n>=load+p.increment);if(top&&next&&exercise.unit!=='bodyweight')return {weight:next,note:`All planned sets reached the top of the range with reported controlled form at effort ≤8. Try ${next} kg if it feels controlled.`};return {weight:load,note:top?'Keep this load; no suitable heavier weight is listed. Add control or a rep.':last.formQuality==='broke-down'?'Reduce the load or range to regain control; stop any painful movement.':'Repeat a comfortable load. Complete all planned sets with controlled form before increasing.'};}
export function weeklyReview(state,end){const p=state.profile;if(state.review.some(r=>r.day>addDays(end,-7)&&r.day<=end))return {enough:false,title:'Review decision saved',text:'Your decision is saved. Keep logging; your next target review is available seven days after your last decision.',delta:null};const from=addDays(end,-13);const c=state.checkins.filter(x=>x.day>=from&&x.day<=end);const recent=c.filter(x=>x.day>addDays(end,-7)&&x.weight>0),prior=c.filter(x=>x.day<=addDays(end,-7)&&x.weight>0);const completeDays=new Set(state.foodLogs.filter(x=>x.complete&&x.day>=from&&x.day<=end).map(x=>x.day));const avg=a=>a.reduce((n,x)=>n+x.weight,0)/a.length;const enough=recent.length>=3&&prior.length>=3&&completeDays.size>=10&&c.filter(x=>x.hunger&&x.energy).length>=7;const t=state.plan?.targets;if(!enough||!t)return {enough:false,title:'Keep your targets steady',text:'Log a few weeks to see trends.',delta:null};const diff=avg(recent)-avg(prior),hungry=c.filter(x=>x.hunger>=4||x.energy<=2).length>=4;return {enough:true,title:hungry?'Consider a little more fuel':'Stay with your current plan',text:`Weekly mean weight changed ${diff>=0?'+':''}${diff.toFixed(2)} kg. ${hungry?'Frequent hunger or low energy suggests trying 100 kcal more daily.':'Continue another week with the current target.'}`,delta:hungry?100:null};}
export function reminders(state){const p=state.profile;if(!p||!state.plan)return [];const events=[];for(const d of state.plan.days){const s=settingsFor(p,d.day);if(d.workout&&p.reminders.workout&&!state.workouts.some(w=>w.day===d.day))events.push({id:d.workout.id,day:d.day,time:d.workout.time,title:'Afterhours Fitness · Training',duration:d.workout.duration});d.meals.forEach((m,i)=>{if(p.reminders.meals[i]&&!state.mealLogs.some(l=>l.id===m.id))events.push({id:m.id,day:d.day,time:m.time,title:'Afterhours Fitness · '+recipe(m.recipe).name,duration:20});});}return events.filter(e=>!inQuiet(e.time,p)&&!isAsleep(e.time,settingsFor(p,e.day))).map(e=>({...e,at:atTime(e.day,e.time,settingsFor(p,e.day).wake,cityInfo(p).zone)}));}
const icsDate=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');
const icsEscape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
export function calendar(state){return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Afterhours//Night shift planner//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',...reminders(state).flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}@afterhours.local`,`SEQUENCE:${state.calendarRevision}`,`DTSTAMP:${icsDate(new Date())}`,`DTSTART:${icsDate(e.at)}`,`DTEND:${icsDate(Date.parse(e.at)+e.duration*60000)}`,`SUMMARY:${icsEscape(e.title)}`,'DESCRIPTION:Day '+e.day+'. '+cityInfo(state.profile).zone+'.','BEGIN:VALARM','TRIGGER:-PT5M','ACTION:DISPLAY',`DESCRIPTION:${icsEscape(e.title)}`,'END:VALARM','END:VEVENT']),'END:VCALENDAR'].join('\r\n');}

export function scaledSteps(r,n){return r.steps.map(s=>s.replace(/(\d+(?:\.\d+)?) (ml|tbsp)\b/g,(_,amount,unit)=>`${+(Number(amount)*n).toFixed(1)} ${unit}`));}
export function household(id,g){const measures={rice:[180,'cup dry'],oats:[80,'cup'],egg:[50,'medium egg(s)'],chicken:[150,'small breast(s)'],tofu:[250,'block(s)'],mung:[200,'cup dry'],sardine:[155,'can(s)'],tuna:[120,'drained can(s)'],banana:[100,'medium banana(s)'],cabbage:[90,'cup shredded'],carrot:[60,'medium carrot(s)'],papaya:[140,'cup cubes'],tomato:[100,'medium tomato(es)'],onion:[70,'small onion(s)'],garlic:[3,'clove(s)'],ginger:[15,'thumb-size piece(s)'],oil:[5,'tsp'],vinegar:[15,'tbsp'],soy:[15,'tbsp']};const [unit,label]=measures[id]||[100,'× 100 g'];return `≈ ${+(g/unit).toFixed(2)} ${label}`;}

export function recipeText(r,n,p,region=regionDefaults){const total=nutrition(r,n,p),one=nutrition(r,1,p);return `${r.name}\nServings: ${n}\nPrep: ${r.prep} min · Cook: ${r.cook} min\n\nIngredients\n`+Object.entries(recipeItems(r,p)).map(([id,g])=>`${+(g*n).toFixed(1)} g ${ingredients[id].name}: ${household(id,g*n)}`).join('\n')+`\nWater as directed, with salt to taste\n\nMethod\n`+scaledSteps(r,n).map((s,i)=>`${i+1}. ${s}`).join('\n')+`\n\nSubstitutions: ${r.subs}\nStorage: ${r.storage}\n\nPer serving: ${Math.round(one.kcal)} kcal · ${Math.round(one.protein)} g protein · ${formatMoney(one.cost,region)}\nTotal: ${Math.round(total.kcal)} kcal · ${Math.round(total.protein)} g protein · ${formatMoney(total.cost,region)}`;}
export function validateBackup(x){validateFoodExtension(x);const ingredients={...catalogIngredients,...supplementalIngredients,...(x?.customIngredients||{})},recipe=id=>[...catalogRecipes,...(x?.customRecipes||[])].find(r=>r.id===id);if(!x||typeof x!=='object'||x.version!==1)throw Error('Unsupported backup version. Use an Afterhours v1 backup.');if(x.region&&(!cities.some(c=>c.id===x.region.city)||!currencies.includes(x.region.currency)||!Number.isFinite(x.region.rate)||x.region.rate<=0||x.region.rate>10000))throw Error('Invalid location or currency.');for(const r of x.customRecipes||[])if(Object.keys(r.items).some(id=>!ingredients[id]))throw Error('Recipe ingredient missing');for(const e of x.foodEntries||[])if(e.kind==='recipe'&&!recipe(e.ref)||e.kind==='ingredient'&&!ingredients[e.ref])throw Error('Logged food reference missing');if(x.profile?.city&&!cities.some(c=>c.id===x.profile.city))throw Error('Invalid city.');const arrays=['workouts','mealLogs','foodLogs','checkins','journal','favorites','extraGroceries','review','recipeHistory'];for(const a of arrays)if(!Array.isArray(x[a])||x[a].length>50000)throw Error(`Invalid ${a} records.`);if(!x.habits||typeof x.habits!=='object'||Array.isArray(x.habits))throw Error('Invalid habit records.');const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s));const number=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;const time=t=>typeof t==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(t);if(x.profile){const p=x.profile;p.trainingPlace||='home';p.timingMode||='manual';p.cookTwice??=false;for(const [key,values] of Object.entries({goal:['consistency','fat loss','build muscle'],experience:['beginner','returning','experienced'],nutrition:['habits','estimates'],sex:['','female','male'],bench:['none','flat','adjustable'],style:['economical','balanced','convenience'],diet:['any','vegetarian']}))if(!values.includes(p[key]))throw Error('Invalid '+key);for(const [key,min,max]of [['age',18,100],['weight',30,300],['height',120,230]])if(p[key]!==null&&!number(p[key],min,max))throw Error('Invalid '+key);if(!number(p.activity,1,2.5)||!p.pantry||!p.prices||typeof p.journey!=='boolean'||typeof p.cookTwice!=='boolean')throw Error('Invalid profile.');for(const k of ['wake','sleep','offWake','offSleep','workout','offWorkout','quietStart','quietEnd','workStart','workEnd'])if(!time(p[k]))throw Error('Invalid schedule.');for(const k of ['meals','offMeals'])if(!Array.isArray(p[k])||p[k].length!==3||!p[k].every(time))throw Error('Invalid meal times.');for(const k of ['workdays','trainDays'])if(!Array.isArray(p[k])||!p[k].every(n=>number(n,0,6)))throw Error('Invalid weekdays.');for(const k of ['equipment','limitations','allergies','kitchen'])if(!Array.isArray(p[k])||!p[k].every(s=>typeof s==='string'))throw Error('Invalid preferences.');for(const k of ['weights','otherLimit','otherAllergy','avoid'])if(typeof p[k]!=='string')throw Error('Invalid text preference.');if(!number(p.minutes,15,90)||!number(p.increment,.25,20)||!number(p.budget,0,100000)||!number(p.prepTime,5,180)||!number(p.prep,0,180))throw Error('Invalid planning values.');if(!p.reminders||typeof p.reminders.workout!=='boolean'||!Array.isArray(p.reminders.meals)||p.reminders.meals.length!==3||!p.reminders.meals.every(v=>typeof v==='boolean'))throw Error('Invalid reminders.');for(const [id,g]of Object.entries(p.pantry||{}))if(!ingredients[id]||!number(g,0,100000))throw Error('Invalid pantry.');for(const [id,v]of Object.entries(p.prices||{}))if(!ingredients[id]||!number(v.price,0,100000)||!number(v.pack,1,100000))throw Error('Invalid prices.');}
for(const [d,h] of Object.entries(x.habits))if(!date(d)||!h||typeof h!=='object'||Object.keys(h).some(k=>!['water','sleep','recovery'].includes(k))||Object.values(h).some(v=>typeof v!=='boolean'))throw Error('Invalid habit record.');for(const r of x.review)if(!date(r.day)||typeof r.decision!=='string')throw Error('Invalid review.');if(x.plan){if(x.plan.targets&&(!number(x.plan.targets.kcal,500,10000)||!number(x.plan.targets.protein,0,1000)))throw Error('Invalid nutrition targets.');if(!x.profile||!date(x.plan.start)||!Array.isArray(x.plan.days)||x.plan.days.length!==7)throw Error('Invalid plan.');for(const d of x.plan.days){if(!date(d.day)||!Array.isArray(d.meals)||d.meals.length>3)throw Error('Invalid planned day.');for(const m of d.meals)if(!recipe(m.recipe)||!number(m.servings,.25,10)||!time(m.time)||typeof m.id!=='string')throw Error('Invalid planned meal.');if(d.workout&&(!time(d.workout.time)||!number(d.workout.duration,15,90)||typeof d.workout.id!=='string'))throw Error('Invalid workout.');}}
for(const w of x.workouts){if(!date(w.day)||!Array.isArray(w.exercises))throw Error('Invalid workout history.');for(const e of w.exercises)if(!exercises.some(a=>a.id===e.id)||!Array.isArray(e.sets)||(e.formQuality!==undefined&&!['','controlled','uncertain','broke-down'].includes(e.formQuality))||(e.plannedSets!==undefined&&!number(e.plannedSets,1,20))||!e.sets.every(s=>number(s.reps,1,100)&&number(s.weight,0,500)&&number(s.rpe,1,10)))throw Error('Invalid exercise log.');}for(const c of x.checkins)if(!date(c.day)||(c.weight!==null&&!number(c.weight,20,400))||!number(c.hunger,1,5)||!number(c.energy,1,5))throw Error('Invalid check-in.');for(const m of x.mealLogs)if(typeof m.id!=='string'||!date(m.day)||!recipe(m.recipe)||!number(m.servings,.25,10))throw Error('Invalid meal log.');for(const f of x.foodLogs)if(!date(f.day)||!number(f.kcal,0,20000)||!number(f.protein,0,1000)||typeof f.complete!=='boolean')throw Error('Invalid food log.');for(const j of x.journal)if(!date(j.day)||typeof j.text!=='string'||j.text.length>10000)throw Error('Invalid journal.');for(const f of x.favorites)if(!recipe(f))throw Error('Invalid favorite.');for(const m of x.extraGroceries)if(!recipe(m.recipe)||!number(m.servings,.25,10))throw Error('Invalid grocery addition.');if(!number(x.calendarRevision,1,1000000))throw Error('Invalid calendar revision.');return x;}

export const rankLadder=[...['Iron','Bronze','Silver','Gold','Platinum','Emerald','Diamond'].flatMap(t=>['IV','III','II','I'].map(d=>t+' '+d)),'Master','Grandmaster','Challenger'];
export function journey(s){
 const entries=(s.foodEntries||[]).filter(entry=>!entry.deletedAt),byDay=new Map();for(const entry of entries){if(!byDay.has(entry.day))byDay.set(entry.day,[]);byDay.get(entry.day).push(entry);}
 const totals=day=>byDay.get(day)?.reduce((sum,entry)=>({kcal:sum.kcal+(entry.nutrition?.kcal||0),protein:sum.protein+(entry.nutrition?.protein||0),sodium:sum.sodium+(entry.nutrition?.sodium||0),saturatedFat:sum.saturatedFat+(entry.nutrition?.saturatedFat||0)}),{kcal:0,protein:0,sodium:0,saturatedFat:0})||{kcal:0,protein:0,sodium:0,saturatedFat:0};
 const fullDays=[...byDay].filter(([,items])=>['breakfast','lunch','dinner'].every(meal=>items.some(item=>item.meal===meal))).map(([day])=>day).sort(),target=s.plan?.targets||{kcal:2000,protein:Math.round((s.profile?.weight||70)*1.6)},proteinDays=[...byDay.keys()].filter(day=>totals(day).protein>=target.protein),rangeDays=[...byDay.keys()].filter(day=>Math.abs(totals(day).kcal-target.kcal)<=target.kcal*.1);
 const streak=days=>{const sorted=[...days].sort().reverse();if(!sorted.length)return 0;let count=1;for(let index=1;index<sorted.length;index++){if(addDays(sorted[index],1)!==sorted[index-1])break;count++;}return count;},fullWeeks=Math.floor(fullDays.length/7),underLimitWeeks=Math.floor([...byDay.keys()].filter(day=>totals(day).sodium<=2000&&totals(day).saturatedFat<=24).length/7),budgetWeeks=0;
 const achievements=[['diary-7','Full diary week','Log breakfast, lunch and dinner for 7 days',fullDays.length,7],['diary-streak','Diary streak','Log all three meals on 7 days in a row',streak(fullDays),7],['protein-7','Protein week','Hit your protein goal on 7 days',proteinDays.length,7],['protein-streak','Protein streak','Hit your protein goal 7 days in a row',streak(proteinDays),7],['calorie-range','Steady intake','Finish 7 days within 10% of your calorie goal',rangeDays.length,7],['recipe-import','Recipe added','Add your first recipe',s.customRecipes?.length||0,1],['meal-saved','Meal saved','Save your first meal',s.savedMeals?.length||0,1],['full-week','First full week','Complete one full diary week',fullWeeks,1],['limits-week','Weekly limits','Stay under sodium and saturated fat limits for 7 logged days',underLimitWeeks,1],['budget-week','Budget week','Finish a week inside your grocery budget',budgetWeeks,1]].map(([id,name,rule,value,target])=>({id,name,rule,value,target,unlocked:value>=target}));
 const movements=new Set(),sessions=new Set();for(const workout of s.workouts||[]){if((workout.exercises||[]).some(exercise=>exercise.sets?.length))sessions.add(workout.day);for(const exercise of workout.exercises||[])if(exercise.sets?.length)movements.add(workout.day+':'+exercise.id);}const plannedMeals=new Set((s.mealLogs||[]).map(meal=>meal.id)),habitCount=Object.values(s.habits||{}).reduce((sum,day)=>sum+Object.values(day).filter(Boolean).length,0),legacyAchievements=[['first','First step','Save one exercise',movements.size,1],['session','Session starter','Save one training session',sessions.size,1]].map(([id,name,rule,value,target])=>({id,name,rule,value,target,unlocked:value>=target}));achievements.unshift(...legacyAchievements);const xp=movements.size*20+sessions.size*30+plannedMeals.size*10+habitCount*10+fullDays.length*30+proteinDays.length*15+rangeDays.length*15,index=Math.min(rankLadder.length-1,Math.floor(xp/250)),next=rankLadder[index+1]||null;
 return {xp,index,rank:rankLadder[index],next,remaining:next?(index+1)*250-xp:0,percent:next?(xp%250)/250*100:100,achievements,movements:0,sessions:(s.workouts||[]).length};
}

export function recommendMeals(p,favorites=[]){const allowed=allowedRecipes(p),info=cityInfo(p),local=allowed.filter(r=>isLocalRecipe(r,info)),pool=local.length?local:allowed,chosen=pool.filter(r=>favorites.includes(r.id));return {recipes:chosen.length?chosen:pool.slice(0,3),chosen:chosen.length>0,blocked:favorites.filter(id=>!allowed.some(r=>r.id===id))};}
export function refreshMeals(plan,p,favorites,logs=[],from=wakingDay(p),options={}){
 const out=structuredClone(plan),logged=new Set(logs.map(l=>l.id)),keptRecipes=plan.days.flatMap(day=>day.meals.filter(meal=>day.day<from||logged.has(meal.id))).map(meal=>meal.recipe),blocked={...(options.blocked||{})};for(const id of keptRecipes)blocked[id]=addDays(from,8);const suggested=buildPlan(p,plan.start,null,[],favorites,{...options,blocked});
 for(const d of out.days){if(d.day<from)continue;const next=suggested.days.find(x=>x.day===d.day);d.meals=d.meals.length?d.meals.map((m,i)=>{if(logged.has(m.id))return m;const n=next.meals[i];return n?{...n,id:m.id,time:m.time}:null;}).filter(Boolean):next.meals;}
 const used=new Set(out.days.flatMap(day=>day.meals).map(meal=>meal.recipe));for(const id of favorites){const favorite=recipe(id);if(!favorite||used.has(id)||!allowedRecipes(p).some(item=>item.id===id)||blocked[id]>=from)continue;const day=out.days.find(day=>day.day>=from&&day.meals.some(meal=>!logged.has(meal.id)&&recipe(meal.recipe)?.mealType===favorite.mealType));if(!day)continue;const meal=day.meals.find(meal=>!logged.has(meal.id)&&recipe(meal.recipe)?.mealType===favorite.mealType),previous=meal.recipe;meal.recipe=id;const cost=groceries(out.days.flatMap(item=>item.meals),p).reduce((sum,item)=>sum+item.purchase,0);if(cost>p.budget)meal.recipe=previous;else{used.delete(previous);used.add(id);}}
 const ingredientCount=new Set(out.days.flatMap(day=>day.meals).flatMap(meal=>Object.keys(recipe(meal.recipe).items))).size;return {...out,poolSize:suggested.poolSize,limitingFilter:suggested.limitingFilter,budgetTight:suggested.budgetTight,ingredientCount,seed:suggested.seed};
}
